```typescript
export type AccountDefinition = {
  secret: string;
  modules: readonly string[];
};

export type ActiveProfile = {
  username: string;
  modules: string[];
};

export class WorkspaceGate {
  private readonly accounts: Record<string, AccountDefinition>;
  private active: ActiveProfile | null = null;
  private tracking = false;
  private activityCount = 0;

  constructor(accounts: Readonly<Record<string, AccountDefinition>>) {
    this.accounts = {};
    for (const [name, account] of Object.entries(accounts)) {
      this.accounts[name] = { secret: account.secret, modules: [...account.modules] };
    }
  }

  async signIn(username: string, secret: string): Promise<ActiveProfile> {
    const account = this.accounts[username];
    if (!account || account.secret !== secret) throw new Error("Invalid credentials");
    this.active = { username, modules: [...account.modules] };
    return { username, modules: [...account.modules] };
  }

  signOut(): void {
    this.active = null;
    this.tracking = false;
  }

  async modules(): Promise<string[]> {
    if (!this.active) throw new Error("Not authenticated");
    return [...this.active.modules];
  }

  startTracking(): void {
    if (!this.active) throw new Error("Not authenticated");
    this.tracking = true;
  }

  stopTracking(): void {
    this.tracking = false;
  }

  recordActivity(): number {
    if (this.tracking) this.activityCount++;
    return this.activityCount;
  }

  loginRoute(): string | null {
    return this.active ? null : "/sign-in";
  }

  resolveDocument(name: string): string {
    if (typeof name !== "string" || name.length === 0) throw new TypeError("Invalid document");
    return `/manual/${name}.html`;
  }
}
