import { WorkspaceGate, type AccountDefinition } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
async function rejectsWith(promise: Promise<unknown>, message: string): Promise<void> {
  let error: unknown;
  try { await promise; } catch (caught) { error = caught; }
  assert(error instanceof Error && error.message === message, `expected rejection: ${message}`);
}
function throwsTypeError(fn: () => void, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

async function run(): Promise<void> {
  const modules = ['dashboard', 'reports'];
  const accounts: Record<string, AccountDefinition> = {
    alice: { secret: 'secret', modules }
  };
  const gate = new WorkspaceGate(accounts);
  modules[0] = 'mutated';
  accounts.alice = { secret: 'changed', modules: [] };
  assert(gate.loginRoute() === '/sign-in', 'initially unauthenticated');
  await rejectsWith(gate.modules(), 'Not authenticated');
  await rejectsWith(gate.signIn('alice', 'wrong'), 'Invalid credentials');

  const profile = await gate.signIn('alice', 'secret');
  deepEqual(profile, { username: 'alice', modules: ['dashboard', 'reports'] }, 'constructor copied definitions');
  assert(gate.loginRoute() === null, 'authenticated route');
  profile.modules.push('admin');
  deepEqual(await gate.modules(), ['dashboard', 'reports'], 'sign-in profile is defensive');
  const exposedModules = await gate.modules();
  exposedModules[0] = 'changed';
  deepEqual(await gate.modules(), ['dashboard', 'reports'], 'modules result is defensive');

  gate.startTracking();
  assert(gate.recordActivity() === 1, 'tracking increments activity');
  assert(gate.recordActivity() === 2, 'tracking count accumulates');
  gate.stopTracking();
  assert(gate.recordActivity() === 2, 'stopped tracking does not increment');
  gate.startTracking();
  await rejectsWith(gate.signIn('alice', 'bad'), 'Invalid credentials');
  assert(gate.loginRoute() === null, 'failed sign-in preserves session');
  assert(gate.recordActivity() === 3, 'failed sign-in preserves tracking state');

  gate.signOut();
  assert(gate.loginRoute() === '/sign-in', 'sign-out clears session');
  assert(gate.recordActivity() === 3, 'sign-out disables tracking');
  await rejectsWith(gate.modules(), 'Not authenticated');
  let trackingError: unknown;
  try { gate.startTracking(); } catch (error) { trackingError = error; }
  assert(trackingError instanceof Error && trackingError.message === 'Not authenticated', 'tracking requires authentication');

  assert(gate.resolveDocument('Guide_2-alpha') === '/manual/Guide_2-alpha.html', 'valid document resolved');
  for (const bad of ['', '.', '..', 'a/b', 'a\\b', 'a b', 'a.html', '../secret', 'é', '\n', 4, null]) {
    throwsTypeError(() => gate.resolveDocument(bad as unknown as string), `invalid document rejected: ${String(bad)}`);
  }
}

void run();

